import assert from 'node:assert/strict';
import {createGardenState,restoreGardenState,stepGarden} from '../../../../src/js/garden/GardenSimulation.js';
import {tickGardenBee,restoreGardenEncounters} from '../../../../src/js/garden/GardenEncounters.js';
const s=createGardenState(),b=s.encounters.bees[0],a={x:b.x,y:b.y},path=[];
s.player.x=b.x-200;s.player.y=b.y+180;b.cooldown=0;
tickGardenBee(b,s,.01);assert.equal(b.phase,'prepare');tickGardenBee(b,s,.5);assert.equal(b.phase,'dive');
for(let i=1;i<=10;i++){tickGardenBee(b,s,.125);path.push({x:b.x,y:b.y});}
assert.equal(b.phase,'patrol');assert.equal(b.perch,1);assert.equal(b.x,b.otherX);assert.equal(b.y,b.otherY);assert.ok(path[4].y>a.y+100,'Parábola passa perto do chão');
const rest={x:b.x,y:b.y};s.player.x=b.x-1000;for(let i=0;i<300;i++)tickGardenBee(b,s,1/120);assert.deepEqual({x:b.x,y:b.y},rest,'Repouso B permanece fixo no ar');
s.player.x=b.x+100;tickGardenBee(b,s,.01);assert.equal(b.phase,'prepare');tickGardenBee(b,s,.5);
for(let i=1;i<=10;i++){tickGardenBee(b,s,.125);const reverse=i===10?a:path[9-i];assert.ok(Math.abs(b.x-reverse.x)<.001);assert.ok(Math.abs(b.y-reverse.y)<.001,'Volta espelha a mesma parábola');if(i===4){const clone=restoreGardenEncounters(structuredClone(s.encounters));assert.deepEqual(clone,s.encounters,'Restore conserva sentido e ponto do voo');}}
assert.equal(b.perch,0);assert.deepEqual({x:b.x,y:b.y},a,'Retorna ao ponto A');
const restored=restoreGardenState(structuredClone(s));assert.equal(restored.version,9);assert.deepEqual(restored.encounters,s.encounters);
for(const phase of ['patrol','prepare','dive','return']){const old=structuredClone(s);old.version=8;const bee=old.encounters.bees[0];bee.phase=phase;bee.age=.2;for(const key of ['perch','otherX','otherY','arcDepth','duration'])delete bee[key];const migrated=restoreGardenState(old);assert.equal(migrated.version,9);assert.equal(migrated.encounters.bees[0].x,bee.x);assert.equal(migrated.encounters.bees[0].y,bee.y);assert.deepEqual(migrated.player,restored.player,'Migração não move a menina');}
const bad=structuredClone(s);bad.encounters.bees[0].otherX+=10;assert.throws(()=>restoreGardenState(bad));
console.log('APROVADO: parábolas A→B→A espelhadas, repouso fixo, aviso, direção, save em voo e migração 8→9 sem teleporte.');
